"""Upload safety checks that need the file's content: generated / minified files (they burn embedding quota and
carry no knowledge) and files that contain a credential (their text would be sent to the embedding and chat
providers). Both are skipped at upload and shown in the upload report; nothing here calls a network.

Secret detection uses only patterns with a distinctive prefix or shape, so ordinary code that merely mentions
`password` or `api_key` is not flagged."""
import re
from pathlib import PurePosixPath

SCAN_BYTES = 5 * 1024 * 1024  # a file is scanned up to this much of its start

_SECRET_PATTERNS: list[tuple[str, re.Pattern]] = [
    ("a private key", re.compile(r"-----BEGIN (?:RSA |EC |DSA |OPENSSH |PGP |ENCRYPTED )?PRIVATE KEY(?: BLOCK)?-----")),
    ("an AWS access key", re.compile(r"\b(?:AKIA|ASIA)[0-9A-Z]{16}\b")),
    ("a GitHub token", re.compile(r"\b(?:gh[pousr]_[A-Za-z0-9]{36,}|github_pat_[A-Za-z0-9_]{50,})\b")),
    ("a Groq API key", re.compile(r"\bgsk_[A-Za-z0-9]{40,}\b")),
    ("an OpenAI-style API key", re.compile(r"\bsk-(?:proj-|live-)?[A-Za-z0-9_-]{32,}\b")),
    ("a Google API key", re.compile(r"\bAIza[0-9A-Za-z_-]{35}\b")),
    ("a Slack token", re.compile(r"\bxox[abprs]-[A-Za-z0-9-]{10,}\b")),
    ("a Stripe live key", re.compile(r"\b[sr]k_live_[0-9a-zA-Z]{24,}\b")),
]

# Files that are credentials by name, whatever they contain.
_SECRET_NAMES = frozenset({
    "credentials.json", "id_rsa", "id_dsa", "id_ecdsa", "id_ed25519", ".htpasswd", ".npmrc", ".pypirc", ".netrc",
})
_SECRET_SUFFIXES = (".pem", ".key", ".p12", ".pfx", ".keystore", ".jks")
_ENV_SAFE_SUFFIXES = (".example", ".sample", ".template", ".dist")

_GENERATED_MARKERS = (b"@generated", b"code generated by", b"automatically generated", b"auto-generated file")
_TEXT_TYPES = ("source", "doc", "other")
_BINARY_EXTENSIONS = {".pdf", ".docx"}
MAX_LINE_CHARS = 5000  # a source file with a line this long is minified or bundled, not written by hand


def secret_by_name(path: str) -> str | None:
    name = PurePosixPath(path).name.lower()
    if name in _SECRET_NAMES or name.endswith(_SECRET_SUFFIXES):
        return "a credentials file"
    if name.startswith(".env") and not name.endswith(_ENV_SAFE_SUFFIXES):
        return "an environment file"
    return None


def find_secret(path: str, data: bytes, file_type: str) -> str | None:
    """What kind of credential the file contains (or is), else None. PDF and Word files are not scanned."""
    by_name = secret_by_name(path)
    if by_name:
        return by_name
    if file_type not in _TEXT_TYPES or PurePosixPath(path).suffix.lower() in _BINARY_EXTENSIONS:
        return None
    text = data[:SCAN_BYTES].decode("utf-8", errors="ignore")
    for label, pattern in _SECRET_PATTERNS:
        if pattern.search(text):
            return label
    return None


def looks_generated(data: bytes, file_type: str) -> bool:
    """True for minified / bundled / machine-written source: a very long line, a source-map footer, or a
    'generated, do not edit' header."""
    if file_type != "source":
        return False
    head = data[:2048]
    if any(marker in head.lower() for marker in _GENERATED_MARKERS):
        return True
    if b"sourceMappingURL=" in data[-2048:]:
        return True
    text = data[:SCAN_BYTES].decode("utf-8", errors="ignore")
    return any(len(line) > MAX_LINE_CHARS for line in text.splitlines())
